scenes.css:
#rf-root,.hf-root{--x3:#3a3a52;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-fadein 0.5s ease-out both,st-zoomout 0.5s cubic-bezier(.7,0,.84,0) 3.5s both;}.cam{position:absolute;inset:0;animation:st-cam 4s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}@property --n131{syntax:'<integer>';inherits:false;initial-value:0}
.n131{counter-reset:n131 var(--n131);animation:n131-c 1.8s cubic-bezier(.16,1,.3,1) 0.55s both}
.n131::after{content:counter(n131,decimal)}
@keyframes n131-c{from{--n131:0}to{--n131:4}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.eb{display:inline-block;font:500 32px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}.acc{color:var(--rf-accent);font-style:normal}.wrap>div:first-child{margin-bottom:40px}
.num{font-size:400px;line-height:.9;font-weight:600;letter-spacing:-.06em;color:var(--rf-text);font-variant-numeric:tabular-nums;transform-origin:left bottom}
.aff{font-size:.5em;letter-spacing:-.02em;margin:0 .04em;color:var(--rf-accent)}
.meter{height:22px;border-radius:99px;background:color-mix(in srgb,var(--rf-text) 12%,transparent);margin:40px 0 10px;overflow:hidden}
.meter i{display:block;height:100%;border-radius:99px;background:var(--rf-accent);transform-origin:left;animation:mt 1.8s cubic-bezier(.16,1,.3,1) 0.55s both}
@keyframes mt{from{transform:scaleX(0)}to{transform:none}}
.lbl{margin-top:36px;font-size:66px;line-height:1.08;font-weight:600;letter-spacing:-.02em;color:var(--rf-text)}
.note{margin:36px 0 0;font-size:42px;line-height:1.3;color:var(--rf-muted)}
